<template><div :class="['wb',{'wb-sidebar-collapsed':sidebarCollapsed}]"><div v-if="deleteTarget" class="wb-delete-overlay" @click.self="deleteTarget=null"><section role="dialog" aria-modal="true" aria-labelledby="delete-title"><h3 id="delete-title">删除会话？</h3><p>“{{deleteTarget.title}}”及其本地聊天记录将被删除。</p><div><button @click="deleteTarget=null">取消</button><button class="danger" @click="deleteSession">确认删除</button></div></section></div><header class="wb-header"><a class="wb-platform-link" href="#/"><span class="wb-brand-mark"><GraphIcon name="品类"/></span><strong>WorkBuddy</strong><span class="wb-platform-name">天然气业务工作台</span></a><a class="wb-back-home" href="#/"><GraphIcon name="home"/>返回首页</a></header><div v-if="config" :class="['wb-layout',{'settings-hidden':!showSettings}]"><aside class="wb-sidebar"><div class="wb-sidebar-tools"><button :aria-label="sidebarCollapsed?'展开侧栏':'收起侧栏'" :title="sidebarCollapsed?'展开侧栏':'收起侧栏'" :aria-expanded="!sidebarCollapsed" @click="sidebarCollapsed=!sidebarCollapsed"><GraphIcon name="panelLeft"/></button><button aria-label="查找历史会话" title="查找历史会话" @click="openHistorySearch"><GraphIcon name="search"/></button><button aria-label="筛选历史会话" title="筛选历史会话" :aria-expanded="historyFilterOpen" :class="{chosen:historyScene}" @click="historyFilterOpen=!historyFilterOpen"><GraphIcon name="filter"/></button></div><div v-if="historyFilterOpen&&!sidebarCollapsed" class="wb-history-filter" @keydown.esc="historyFilterOpen=false"><div><b>筛选会话</b><button aria-label="关闭会话筛选" @click="historyFilterOpen=false"><GraphIcon name="close"/></button></div><select v-model="historyScene" aria-label="筛选会话场景"><option value="">全部场景</option><option v-for="item in config.scenes" :key="item.id">{{item.id}}</option></select></div><div class="wb-side-brand"><strong>WorkBuddy</strong><small>天然气业务</small></div><a class="wb-nav-item wb-home-nav" href="#/" aria-label="返回首页" title="返回首页"><GraphIcon name="home"/><span>返回首页</span></a><button class="wb-nav-item" @click="newSession"><SidebarIcon name="new"/>新建任务</button><button :class="['wb-nav-item',{active:navPanel==='schedule'}]" @click="navPanel='schedule'"><SidebarIcon name="schedule"/>定时任务</button><button :class="['wb-nav-item',{active:navPanel==='library'}]" @click="navPanel='library'"><SidebarIcon name="library"/>知识库</button><button :class="['wb-nav-item',{active:navPanel==='recent'||navPanel==='forecast'}]" @click="toggleRecent"><SidebarIcon name="history"/>最近预测<span class="wb-recent-chevron">{{recentExpanded?'⌃':'⌄'}}</span></button><div v-if="recentExpanded" class="wb-forecast-tree"><button v-for="prediction in allPredictions" :key="prediction.id" :class="{chosen:navPanel==='forecast'&&prediction.id===selectedPrediction?.id}" @click="selectedPrediction=prediction;navPanel='forecast'"><strong>{{prediction.title}}</strong><small>{{prediction.horizon}} · {{prediction.unit}}</small></button><p v-if="!allPredictions.length">暂无预测记录</p></div><button :class="['wb-nav-item',{active:navPanel==='graph'}]" @click="navPanel='graph'"><GraphIcon name="graph"/>图谱探索</button><div class="wb-recent-heading"><p class="wb-recent-label">最近会话</p><label v-if="sessions.length>4||historySearchVisible" class="wb-session-search"><GraphIcon name="search"/><input ref="historySearchInput" v-model="sessionQuery" aria-label="搜索历史会话" placeholder="搜索会话"></label></div><div class="wb-session-scroll"><p v-if="!filteredSessions.length" class="wb-history-empty">暂无匹配会话</p><div v-for="session in filteredSessions" :key="session.id" :class="['wb-session-row',{chosen:activeSession===session.id&&!navPanel}]"><form v-if="renaming===session.id" class="wb-rename-form" @submit.prevent="saveName(session)"><input v-model="renameText" autofocus maxlength="60" aria-label="会话名称" @keydown.esc="renaming='' "><button type="submit">保存</button><button type="button" @click="renaming=''">取消</button></form><template v-else><button class="wb-session-open" @click="loadSession(session.id);navPanel=''" :title="session.title"><span>{{session.title}}</span><small>{{relativeTime(session.updatedAt)}}</small></button><button class="wb-session-rename" @click="renaming=session.id;renameText=session.title" title="重命名会话" aria-label="重命名会话"><GraphIcon name="edit"/></button><button class="wb-session-delete" @click="deleteTarget=session" title="删除会话" aria-label="删除会话"><GraphIcon name="trash"/></button></template></div></div><div class="wb-sidebar-settings"><button @click="capabilityTab='连接器';navPanel='experts'">服务连接</button><a href="#/">返回首页</a></div></aside><div v-if="navPanel" :class="['wb-resource-backdrop',{'wb-forecast-page':navPanel==='forecast','wb-schedule-page':navPanel==='schedule'||navPanel==='graph'||navPanel==='forecast'||navPanel==='library'}]" @click.self="navPanel=''"><section class="wb-resource"><div class="wb-resource-heading"><h2>{{{experts:capabilityTab,schedule:'定时任务',library:'知识库',recent:'最近预测',forecast:'预测详情',graph:'图谱探索',discover:'发现'}[navPanel]}}</h2><button @click="navPanel=''" :aria-label="navPanel==='forecast'?'关闭预测详情':'关闭面板'"><GraphIcon name="close"/></button></div><template v-if="navPanel==='experts'"><CapabilityManager :initial-tab="capabilityTab" @tab-change="capabilityTab=$event" @choose="chooseSkill"><p>七个智能体组成协作团队：三类预测专家负责业务结果，四类共享专家提供数据分析与依据。</p><div class="wb-expert-grid"><button v-for="s in config.scenes" :key="s.id" @click="expertInfo=s.id"><strong>{{s.id}}智能体</strong><small>{{s.subtitle}}</small><span>{{['短期客户','冬季保供','月度销量'].includes(s.id)?'业务预测专家':'共享支撑专家'}}</span></button></div><p v-if="expertInfo" class="wb-expert-description">{{expertInfo}}智能体：{{expertRoles[expertInfo]}}</p></CapabilityManager></template><template v-else-if="navPanel==='forecast'"><ForecastDetail :record="selectedPrediction"/></template><template v-else-if="navPanel==='graph'"><GraphExplorer @analyze="useGraphContext"/></template><template v-else-if="navPanel==='recent'"><p>查看已保存的预测记录</p><div v-if="!allPredictions.length" class="wb-empty-resource"><h3>暂无预测结果</h3><p>完成预测后，结果将在这里展示。</p></div><div class="wb-recent-list"><button v-for="prediction in allPredictions" :key="prediction.id" @click="selectedPrediction=prediction;navPanel='forecast'"><GraphIcon name="需求变化"/><div><b>{{prediction.title}}</b><small>{{prediction.horizon}} · {{prediction.unit}}</small></div><GraphIcon name="chevron"/></button></div></template><template v-else-if="navPanel==='library'"><KnowledgeLibrary @ask="useKnowledge"/></template><template v-else-if="navPanel==='discover'"><p>从业务模板开始新任务</p><button class="wb-library-item" v-for="s in config.scenes.slice(0,3)" :key="s.id" @click="newSession();switchScene(s);input=s.prompts[0];navPanel=''">{{s.id}}预测<small>{{s.subtitle}}</small></button></template><template v-else><ScheduledTasks @run="runScheduled"/></template></section></div><section :inert="Boolean(navPanel)" :class="['wb-conversation',{'wb-start':!messages.length||entryMode==='manual','wb-manual':entryMode==='manual','wb-active-conversation':messages.length>0&&entryMode==='chat','wb-has-report':Boolean(conversationPrediction)&&entryMode==='chat'}]"><div class="wb-title"><section class="wb-entry-switch" role="group" aria-label="发起预测方式"><button :class="{chosen:entryMode==='chat'}" :aria-pressed="entryMode==='chat'" @click="setEntryMode('chat')"><SidebarIcon name="new"/>会话预测</button><button :class="{chosen:entryMode==='manual'}" :aria-pressed="entryMode==='manual'" @click="setEntryMode('manual')"><GraphIcon name="sliders"/>手动预测</button></section><div><p class="wb-label">{{scene.id}} · {{objectSummary}}</p><h1>{{currentSession?.title||'业务会话'}}</h1></div><button v-if="entryMode==='chat'" class="wb-secondary" :aria-label="showSettings?'收起参数':'业务参数'" :title="showSettings?'收起参数':'业务参数'" :aria-expanded="showSettings" @click="showSettings=!showSettings"><GraphIcon name="panelRight"/><span class="wb-parameter-label">{{showSettings?'收起参数':'业务参数'}}</span></button></div><div v-if="!conversationPrediction" class="wb-context"><span>{{scene.objectLabel}}：{{objectSummary}}</span><span>周期：{{period}}</span><span v-if="scene.id==='月度销量'">{{industry}}</span><b>{{scene.unit}}</b></div><ManualForecast v-if="entryMode==='manual'" :config="config" :scene="scene" :customers="customerOptions" v-model:customer-ids="selectedCustomerIds" v-model:object="object" v-model:period="period" v-model:industry="industry" v-model:supply="supply" @scene="switchScene(config.scenes.find(s=>s.id===$event))" @submit="startManualForecast"/><div v-show="entryMode==='chat'" ref="messageList" class="wb-messages"><div class="wb-welcome" v-if="!messages.length"><h2>WorkBuddy，我帮你</h2></div><article v-for="(message,i) in messages" :key="i" :class="['wb-message',message.role]"><span class="wb-avatar">{{message.role==='user'?'我':'W'}}</span><div><small>{{message.role==='user'?'我的需求':message.agent}}</small><p>{{message.role==='user'?message.text:workspaceCopy(message.text)}}</p><div v-if="message.sources?.some(source=>source.url)" class="wb-message-sources" aria-label="参考资料"><a v-for="source in message.sources.filter(source=>source.url)" :key="source.id||source.url" :href="source.url" target="_blank" rel="noopener noreferrer"><span>{{source.publisher}} · {{source.publishedAt}}</span><strong>{{source.title}}</strong></a></div></div></article><section v-if="conversationPrediction" ref="inlinePrediction" class="wb-inline-prediction" aria-label="会话预测完整结果"><ForecastDetail :record="conversationPrediction" id-prefix="conversation-forecast" presentation="conversation"/></section><div v-else-if="result" class="wb-result"><details class="wb-result-info"><summary>计算与来源</summary><dl><dt>计算方式</dt><dd>{{result.predictionRecord?'已保存预测记录':'规则计算'}}</dd><dt>参数来源</dt><dd>{{result.predictionRecord?'预测结果记录':result.customers?'客户销量与业务系数':'预置业务参数'}}</dd><dt>模型调用</dt><dd>未执行</dd></dl><p v-if="result.predictionRecord">记录来源：{{result.sourceFile}}；数据截止 {{result.predictionRecord.dataThrough}}；采用模型 {{result.predictionRecord.selectedModel}}。</p><template v-else-if="result.customers"><p v-for="customer in result.customers" :key="customer.customerId">{{customer.name}}：{{customer.baselineSource}}<span v-if="customer.dataThrough">；数据截止 {{customer.dataThrough}}</span></p></template><p v-else>当前结果由所选对象、周期与业务系数计算，天气、实绩和模型回测以对应记录为准。</p></details><div class="wb-result-head"><h3>{{result.object}} · {{result.period}}</h3><span>{{result.status==='unavailable'?'待补充数据':result.unavailable?'部分已生成':'已生成'}}</span></div><p>{{result.industry}} · {{result.unit}} · 单位：万方</p><div class="wb-summary"><div>预测合计<strong>{{result.total??'—'}}</strong></div><div>峰值需求<strong>{{result.peak??'—'}}</strong></div><div>结果明细<strong>{{result.rows.length}} 期</strong></div></div><CustomerBatchSummary v-if="result.customers?.length" :customers="result.customers"/><div v-if="result.rows.length" class="wb-bars"><div v-for="row in result.rows" :key="row.label"><span :style="{height:(result.peak>0?row.value/result.peak*90:0)+'px'}" :title="row.value+' 万方'"></span><small>{{row.label}}</small></div></div><details><summary>查看预测明细</summary><table><thead><tr><th>周期</th><th>需求（万方）</th></tr></thead><tbody><tr v-for="row in result.rows" :key="row.label"><td>{{row.label}}</td><td>{{row.value}}</td></tr></tbody></table></details><div class="wb-result-actions"><button class="wb-secondary" @click="download">导出结果 CSV</button></div></div></div><div class="wb-quick-scenes wb-bottom-scenes" v-if="!messages.length&&entryMode==='chat'"><button v-for="quick in quickScenes" :key="quick.label" @mouseenter="previewPrompt=quick.prompt" @mouseleave="previewPrompt=''" @focus="previewPrompt=quick.prompt" @blur="previewPrompt=''" @click="useQuickScene(quick)"><GraphIcon :name="quick.icon"/>{{quick.label}}</button></div><form v-show="entryMode==='chat'" class="wb-composer" @submit.prevent="send"><div v-if="selectedSkills.length" class="wb-skill-tags"><button type="button" v-for="skill in selectedSkills" :key="skill.id" @click="selectedSkills=selectedSkills.filter(s=>s.id!==skill.id)">{{skill.name}} ×</button></div><div v-if="graphContext" class="wb-knowledge-context"><span>已引用原始图谱资料</span><button type="button" @click="graphContext=''">移除 ×</button></div><div v-if="knowledgeContext" class="wb-knowledge-context"><span>引用资料：{{knowledgeContext.title}} · V{{knowledgeContext.version}}</span><button type="button" @click="knowledgeContext=null">移除 ×</button></div><div v-if="conversationAttachments.length" class="wb-attachments"><span v-for="file in conversationAttachments" :key="file.id"><strong :title="file.title">{{file.title}}</strong><small>{{file.readable?'可引用':'待解析'}}</small><button type="button" @click="conversationAttachments=conversationAttachments.filter(f=>f.id!==file.id)" :aria-label="'移除附件'+file.title">×</button></span></div><p v-if="attachmentMessage" class="wb-attachment-message" role="status">{{attachmentMessage}}</p><textarea ref="composerInput" :rows="messages.length?1:2" v-model="input" aria-label="任务需求" :placeholder="previewPrompt||(messages.length?'继续提问，或补充预测要求…':'描述你的任务，例如：预测江苏未来3个月天然气销量')" @keydown.ctrl.enter.prevent="send" @keydown.meta.enter.prevent="send"></textarea><div class="wb-composer-footer"><small>{{sendShortcut}} 发送</small><div class="wb-send-controls"><div class="wb-model-picker"><button type="button" class="wb-model-toggle" aria-haspopup="menu" :aria-expanded="modelMenu" @click="modelMenu=!modelMenu">{{modelName}} <span>⌃</span></button><template v-if="modelMenu"><button type="button" class="wb-model-backdrop" aria-label="关闭模型选择" @click="modelMenu=false"></button><div class="wb-model-menu" role="menu" @keydown.esc="modelMenu=false"><p>选择对话模型 <small>模型版本</small></p><button type="button" role="menuitemradio" :aria-checked="selectedModel===model.id" v-for="model in config.models" :key="model.id" @click="selectedModel=model.id;modelMenu=false"><div><strong>{{model.name}}</strong><small>{{model.description}}</small></div><span v-if="selectedModel===model.id">✓</span></button><footer>预测计算方法以结果记录为准。</footer></div></template></div><button class="wb-send-button" type="submit" :disabled="!input.trim()||sending" :aria-label="sending?'正在处理':'发送'" :title="sending?'正在处理':'发送'"><GraphIcon name="send"/></button></div></div></form></section><aside class="wb-settings"><div class="wb-settings-heading"><div><small>任务配置</small><h2>业务参数</h2></div><button aria-label="关闭业务参数" @click="showSettings=false"><GraphIcon name="close"/></button></div><label>业务场景<select aria-label="业务场景" :value="scene.id" @change="switchScene(config.scenes.find(s=>s.id===$event.target.value))"><option v-for="s in config.scenes" :key="s.id" :value="s.id">{{s.id}}</option></select></label><CustomerPicker v-if="scene.id==='短期客户'" :options="customerOptions" v-model="selectedCustomerIds"/><label v-else>{{scene.objectLabel}}<select v-model="object" :aria-label="scene.objectLabel"><option v-for="o in scene.objects" :key="o">{{o}}</option></select></label><label>{{isForecast?'预测周期':'分析范围'}}<select v-model="period" :aria-label="isForecast?'预测周期':'分析范围'"><option v-for="p in scene.periods" :key="p">{{p}}</option></select></label><label v-if="scene.id==='月度销量'">行业<select v-model="industry"><option v-for="i in config.industries" :key="i">{{i}}</option></select></label><label v-if="scene.id==='冬季保供'">可用供气量（万方 / 期，可选）<input v-model="supply" type="number" min="0" step="0.1" placeholder="输入各期可用供气量"></label><div class="wb-settings-note"><strong>场景说明</strong><p v-if="scene.id==='短期客户'">选择一个或多个客户，分别输出日度需求，并汇总同一周期的需求。</p><p v-else-if="scene.id==='冬季保供'">以区域为对象，按旬展示需求；填写供气量后可比较缺口。</p><p v-else-if="scene.id==='月度销量'">以省份、行业为对象，按月展示需求变化。</p><p v-else>选择业务对象和范围，结合已引用资料开展分析。</p></div><details class="wb-settings-source"><summary>计算与来源</summary><p>预测采用预置业务系数计算；资料问答返回原文匹配片段，图谱分析保留引用关系。外部模型服务尚未连接。</p></details></aside></div><p v-else class="wb-loading">{{error||'正在加载工作台…'}}</p></div></template>
<script setup>
import {ref,shallowRef,computed,onMounted,onBeforeUnmount,nextTick,watch} from 'vue'
import CapabilityManager from './CapabilityManager.vue'
import ScheduledTasks from './ScheduledTasks.vue'
import SidebarIcon from './SidebarIcon.vue'
import ForecastDetail from './ForecastDetail.vue'
import KnowledgeLibrary from './KnowledgeLibrary.vue'
import {knowledgeFiles,referenceExcerpt} from './knowledgeFiles.js'
import GraphExplorer from './GraphExplorer.vue'
import GraphIcon from './GraphIcon.vue'
import {workspaceCopy} from './workspacePresentation.js'
import {completedForecastConversation,completedForecastSessionId,completedForecastSeedKey,reconcileCompletedForecastAverage} from './forecastConversation.js'
import {knowledgeRetrievalConversation,knowledgeConversationSessionId,knowledgeConversationSeedKey} from './knowledgeConversation.js'
import ManualForecast from './ManualForecast.vue'
import CustomerPicker from './CustomerPicker.vue'
import CustomerBatchSummary from './CustomerBatchSummary.vue'
import {createCustomerOptions,createCustomerForecast,manualForecastPrompt,customerForecastCsv} from './customerForecast.js'
const capabilityTab=ref('专家');const selectedSkills=ref([]);function chooseSkill(item){if(!selectedSkills.value.some(s=>s.id===item.id))selectedSkills.value.push({id:item.id,name:item.name});navPanel.value=''}
const conversationAttachments=ref([]),sending=ref(false),attachmentMessage=ref('');
const graphContext=ref('');function useGraphContext(text){entryMode.value='chat';graphContext.value=text;knowledgeContext.value=null;input.value=text;navPanel.value=''}
const knowledgeContext=ref(null);function useKnowledge(document){entryMode.value='chat';graphContext.value='';knowledgeContext.value=document;input.value='请根据《'+document.title+'》说明：';navPanel.value=''}
const quickScenes=[{label:'短期客户预测',icon:'需求变化',scene:'短期客户',prompt:'预测该客户未来7天用气需求，结合历史销量和天气变化说明依据。'},{label:'冬季保供预测',icon:'sun',scene:'冬季保供',prompt:'预测该区域未来三旬用气需求，分析冬季保供风险。'},{label:'月度销量预测',icon:'指标值',scene:'月度销量',prompt:'预测该省未来3个月天然气销量，说明行业构成与变化原因。'},{label:'销量分析',scene:'销量分析',icon:'指标值',prompt:'请分析所选对象的历史销量趋势、同比变化与异常波动。'},{label:'天气影响',scene:'天气分析',icon:'sun',prompt:'请分析所选地区的天气变化对天然气需求的影响。'},{label:'事理分析',scene:'事理分析',icon:'graph',prompt:'请分析相关事件对天然气用气需求的影响，梳理事件、影响范围和传导关系，并说明分析依据。'},{label:'知识问答',scene:'知识问答',icon:'library',prompt:'请介绍天然气销量统计口径，并提供知识来源。'}];function useQuickScene(quick){entryMode.value='chat';if(quick.scene)switchScene(config.value.scenes.find(s=>s.id===quick.scene));input.value=quick.prompt;previewPrompt.value='';nextTick(()=>composerInput.value?.focus());}
const expertInfo=ref('');const expertRoles={'短期客户':'汇总相关分析，生成客户日度需求预测。','冬季保供':'汇总区域需求与供气约束，分析旬度保供需求。','月度销量':'结合省份及行业特征，形成月度销量预测。','天气分析':'为各预测场景分析气温、降温及天气变化影响。','销量分析':'为各预测场景提供历史销量、趋势与波动分析。','事理分析':'梳理事件与需求之间的影响链，辅助解释变化。','知识问答':'检索业务知识及统计口径，为分析提供可追溯依据。'};const participants=computed(()=>[scene.value.id,'天气分析','销量分析','事理分析','知识问答']);const navPanel=ref('');const modelMenu=ref(false),selectedModel=ref('auto');const modelName=computed(()=>config.value?.models?.find(m=>m.id===selectedModel.value)?.name||'自动选择');const showSettings=ref(false);const config=ref(null),scene=ref({}),object=ref(''),period=ref(''),industry=ref('全部行业'),supply=ref(''),input=ref(''),messages=ref([]),result=ref(null),error=ref('')
const entryMode=ref('chat'),customerOptions=shallowRef([]),selectedCustomerIds=ref([])
const selectedCustomers=computed(()=>{const options=new Map(customerOptions.value.map(c=>[c.id,c]));return [...new Set(selectedCustomerIds.value)].map(id=>options.get(id)).filter(Boolean)})
const objectSummary=computed(()=>scene.value.id==='短期客户'?(selectedCustomers.value.length>1?`${selectedCustomers.value.length} 个客户`:selectedCustomers.value[0]?.name||'未选择客户'):object.value)
function setEntryMode(mode){if(mode==='manual'){if(!isForecast.value)switchScene(config.value.scenes.find(s=>s.id==='短期客户'));showSettings.value=false}entryMode.value=mode}
async function startManualForecast(){
 if(sending.value||!period.value||(scene.value.id==='短期客户'?!selectedCustomers.value.length:!object.value))return
 const request={scene:scene.value.id,customers:[...selectedCustomers.value],object:object.value,period:period.value,industry:industry.value,supply:supply.value}
 newSession();switchScene(config.value.scenes.find(s=>s.id===request.scene))
 selectedCustomerIds.value=request.customers.map(c=>c.id);object.value=request.object;period.value=request.period;industry.value=request.industry;supply.value=request.supply
 entryMode.value='chat';showSettings.value=false;input.value=manualForecastPrompt(request);saveParameters();snapshot();await nextTick();await send()
}
const isForecast=computed(()=>['短期客户','冬季保供','月度销量'].includes(scene.value.id))
watch(selectedModel,value=>{try{localStorage.setItem('wb-model',value)}catch{}})
