function sessionPredictionRecords(session){
 const r=session.result;if(!r?.rows?.length)return []
 if(r.predictionRecord)return [{...r.predictionRecord,conversationId:session.id,sortTime:session.updatedAt||Date.parse(r.predictionRecord.createdAt)}]
 const common={scene:session.scene,unit:r.unit,volumeUnit:'万方',horizon:r.period,createdAt:session.updatedAt?new Date(session.updatedAt).toISOString():'未记录',sortTime:session.updatedAt||0,status:r.unavailable?'部分已生成':'已完成',simulated:true,modelExecuted:false,calculationMethod:r.calculationMethod,models:[],backtest:[],weather:[],features:[],notes:['会话规则计算记录；未保存天气、特征和回测详情。']}
 const aggregate={...common,id:session.id,title:session.title,object:r.object,rows:r.rows,customers:r.customers}
 if(!r.customers)return [aggregate]
 const individual=r.customers.filter(c=>c.status==='success').map(c=>({...common,id:r.customers.length===1?session.id:session.id+':'+c.customerId,title:c.name+' · '+r.period,object:c.name,rows:c.rows,dataThrough:c.dataThrough,notes:[...common.notes,'参数来源：'+c.baselineSource,'资料来源：'+c.source]}))
 if(r.customers.length===1)return individual
 aggregate.notes=[...common.notes,`客户范围：${r.customers.map(c=>c.name).join('、')}。${r.successful} 个客户已生成${r.unavailable?'；'+r.unavailable+' 个客户缺少完整月销量':''}。`,...r.customers.map(c=>c.name+'：'+c.baselineSource)]
 return [aggregate,...individual]
}
const conversationPrediction=computed(()=>{
 const r=result.value;if(!r?.rows?.length)return null
 if(r.predictionRecord)return r.predictionRecord
 const current=currentSession.value
 return sessionPredictionRecords({id:current?.id||'conversation-result',title:current?.title||r.object,scene:r.scene||current?.scene||scene.value.id,updatedAt:current?.updatedAt,result:r})[0]||null
})
const allPredictions=computed(()=>{const seen=new Set();return [...sessions.value.flatMap(sessionPredictionRecords),...forecastExamples.value.map(r=>({...r,sortTime:Date.parse(r.createdAt)}))].filter(r=>{if(seen.has(r.id))return false;seen.add(r.id);return true}).sort((a,b)=>b.sortTime-a.sortTime)});const recentForecasts=computed(()=>sessions.value.filter(s=>s.result?.rows?.length).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0)));
function uniqueTitle(title,exclude){const names=new Set(sessions.value.filter(s=>s.id!==exclude).map(s=>s.title));let candidate=title,n=2;while(names.has(candidate))candidate=title+'（'+n+++'）';return candidate}
function normalizeTitles(){const used=new Set();for(const session of sessions.value){let base=session.title||'业务任务';let value=base,n=2;while(used.has(value))value=base+'（'+n+++'）';session.title=value;used.add(value)}}
let parameters={}
function snapshot(){const current=sessions.value.find(s=>s.id===activeSession.value);if(!current)return;current.messages=[...messages.value];current.result=result.value;current.scene=scene.value.id;current.parameters=JSON.parse(JSON.stringify(parameters));current.input=input.value;current.knowledge=knowledgeContext.value;current.graphContext=graphContext.value;current.attachments=[...conversationAttachments.value];try{localStorage.setItem('wb-sessions',JSON.stringify(sessions.value))}catch{}}
function saveParameters(){if(scene.value.id)parameters[scene.value.id]={object:object.value,period:period.value,industry:industry.value,supply:supply.value,...(scene.value.id==='短期客户'?{customerIds:[...selectedCustomerIds.value]}:{})}}
function switchScene(s){
 if(!s)return
 saveParameters();scene.value=s;const saved=parameters[s.id]
 object.value=saved?.object||s.objects[0];period.value=saved?.period||s.periods[0];industry.value=saved?.industry||'全部行业';supply.value=saved?.supply??''
 if(s.id==='短期客户'){
  const ids=saved?.customerIds??[customerOptions.value.find(c=>c.name===object.value)?.id].filter(Boolean)
  selectedCustomerIds.value=[...new Set(ids)].filter(id=>customerOptions.value.some(c=>c.id===id))
  object.value=selectedCustomers.value[0]?.name||''
 }
 snapshot();history.replaceState(null,'','#/workbuddy?scene='+encodeURIComponent(s.id))
}
function newSession(){navPanel.value='';previewPrompt.value='';sessionQuery.value='';saveParameters();snapshot();const id=String(Date.now())+'-'+Math.random().toString(36).slice(2,6);sessions.value.unshift({id,title:uniqueTitle((scene.value.id||'月度销量')+' · '+(object.value||scene.value.objects?.[0]||'待选对象')),autoTitle:true,updatedAt:Date.now(),messages:[],result:null,scene:scene.value.id||'月度销量',parameters:{},input:''});activeSession.value=id;parameters={};messages.value=[];result.value=null;input.value='';knowledgeContext.value=null;graphContext.value='';conversationAttachments.value=[];attachmentMessage.value='';snapshot()}
function reset(){newSession()}
function loadSession(id){entryMode.value='chat';saveParameters();snapshot();const session=sessions.value.find(s=>s.id===id);if(!session)return;activeSession.value=id;parameters=JSON.parse(JSON.stringify(session.parameters||{}));scene.value={};messages.value=[...session.messages];result.value=session.result||null;input.value=session.input||'';knowledgeContext.value=session.knowledge||null;graphContext.value=session.graphContext||'';conversationAttachments.value=[...(session.attachments||[])];attachmentMessage.value='';switchScene(config.value.scenes.find(s=>s.id===session.scene)||config.value.scenes[2])}

onMounted(async()=>{try{const r=await fetch('/workbuddy.json');if(!r.ok)throw Error();config.value=await r.json();const customerScene=config.value.scenes.find(s=>s.id==='短期客户');customerOptions.value=createCustomerOptions(null,customerScene);try{const graph=await fetch('/customer-graph.json');if(graph.ok)customerOptions.value=createCustomerOptions(await graph.json(),customerScene)}catch{};try{const saved=localStorage.getItem('wb-model');if(config.value.models.some(m=>m.id===saved))selectedModel.value=saved}catch{};const id=new URLSearchParams(location.hash.split('?')[1]).get('scene');scene.value=config.value.scenes.find(s=>s.id===id)||config.value.scenes[2];try{const saved=JSON.parse(localStorage.getItem('wb-sessions')||'[]');if(Array.isArray(saved))sessions.value=saved.filter(s=>s.id&&Array.isArray(s.messages))}catch{};const initial=scene.value;for(const session of sessions.value){if(session.title==='新会话'&&!session.customTitle){const first=session.messages.find(m=>m.role==='user'&&m.text);const cfg=session.parameters?.[session.scene];session.title=first?first.text.slice(0,24):(session.scene||'月度销量')+' · '+(cfg?.object||'待选对象');session.autoTitle=!first}if(!session.updatedAt){const parsed=Number(String(session.id).split('-')[0]);if(parsed>1000000000000&&parsed<=Date.now())session.updatedAt=parsed}}normalizeTitles();const latest=sessions.value.find(t=>t.scene===initial.id);if(latest){activeSession.value='';loadSession(latest.id)}else{newSession();switchScene(initial)}await loadForecastRecords();await loadKnowledgeConversation()}catch{error.value='工作台配置加载失败，请刷新重试'}})
async function send(){const text=input.value.trim();if(!text||sending.value)return;if(scene.value.id==='短期客户'&&!selectedCustomers.value.length&&!knowledgeContext.value&&!graphContext.value&&!conversationAttachments.value.length){attachmentMessage.value='请选择至少一个客户';showSettings.value=true;return}const sessionId=activeSession.value;const references=[];const pending=[];if(knowledgeContext.value)references.push(knowledgeContext.value);if(conversationAttachments.value.length){sending.value=true;try{for(const attachment of conversationAttachments.value){const doc=await knowledgeFiles('get',attachment.id);if(!doc)throw new Error('附件已丢失，请重新上传：'+attachment.title);if(doc.sections.length)references.push({title:doc.title,content:doc.sections.map(s=>s.text).join('\n')});else pending.push(doc.title)}}catch(error){attachmentMessage.value=error.message||'读取附件失败，请重试';sending.value=false;return}sending.value=false;if(activeSession.value!==sessionId)return;}const current=sessions.value.find(s=>s.id===activeSession.value);if(current){current.updatedAt=Date.now();if(!current.customTitle&&(current.autoTitle||current.title==='新会话')){current.title=uniqueTitle(text.slice(0,32),current.id);current.autoTitle=false;}}messages.value.push({role:'user',text:text+(references.length?'\n\n引用资料：'+references.map(r=>'《'+r.title+'》').join('、'):'')+(pending.length?'\n待解析附件：'+pending.join('、'):'')});input.value='';result.value=null;if(references.length||pending.length){messages.value.push({role:'assistant',agent:'知识问答智能体',model:modelName.value,text:(references.length?'已关联所选资料，以下为匹配的原文片段：\n\n'+references.map(r=>'【'+r.title+'】\n'+referenceExcerpt(r.content,text)).join('\n\n'):'')+(pending.length?'\n\n以下文件已保存，正文待解析，暂不能用于问答：'+pending.join('、'):'')});snapshot();return}if(graphContext.value){messages.value.push({role:'assistant',agent:'图谱分析',model:modelName.value,text:'已关联所选图谱对象与关系，以下为引用内容及来源：\n\n'+graphContext.value});snapshot();return}if(!isForecast.value){messages.value.push({role:'assistant',agent:'WorkBuddy 协同助理',model:modelName.value,text:`已记录「${object.value}」的分析需求。请在知识库选择资料，或从图谱探索引用对象，以便核对分析依据。`});return}if(scene.value.id==='短期客户'){
 const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date())
 const batch=createCustomerForecast({customers:selectedCustomers.value,factors:config.value.factors,days:parseInt(period.value.match(/\d+/)[0]),today})
 result.value={...batch,object:objectSummary.value,period:period.value,unit:'日度',industry:'全部行业'}
 messages.value.push({role:'assistant',agent:'WorkBuddy 协同助理',model:modelName.value,text:batch.successful?`已为 ${batch.successful} 个客户生成${period.value}的日度需求，按客户保留明细${batch.successful>1?'并汇总同一周期需求':''}。${batch.unavailable?`另有 ${batch.unavailable} 个客户缺少完整月销量，请补充数据后重试。`:''}`:'所选客户缺少完整月销量，请补充数据后重新发起预测。'})
 snapshot();return
}const count=scene.value.id==='短期客户'?parseInt(period.value.match(/\d+/)[0]):scene.value.id==='月度销量'?(period.value.includes('6')?6:3):period.value==='本供暖季'?12:3;const factor=1+scene.value.objects.indexOf(object.value)*.07;const industryFactor=industry.value==='全部行业'?1:[.482,.326,.137][config.value.industries.indexOf(industry.value)-1];const rows=Array.from({length:count},(_,i)=>({label:scene.value.unit==='日度'?`第${i+1}天`:scene.value.unit==='月度'?`第${i+1}月`:`第${i+1}旬`,value:+(scene.value.base*config.value.factors[i]*factor*industryFactor).toFixed(2)}));const peak=Math.max(...rows.map(r=>r.value));result.value={simulated:true,calculationMethod:'rules',modelExecuted:false,steps:[{agent:'销量分析',description:'读取所选对象的历史销量与波动特征。'},{agent:'天气分析',description:'提供所选范围的气象影响分析。'},{agent:'事理分析',description:'梳理可能影响用气的事件与传导关系。'},{agent:'知识问答',description:'提供统计口径与业务知识参考。'},{agent:scene.value.id,description:'按所选对象与周期进行规则计算。'}],object:object.value,period:period.value,unit:scene.value.unit,industry:scene.value.id==='月度销量'?industry.value:'全部行业',rows,peak,total:rows.reduce((a,r)=>a+r.value,0).toFixed(2)};let advice='';if(scene.value.id==='冬季保供'&&supply.value!==''){const gap=Math.max(0,peak-Number(supply.value));advice+=gap>0?`按每期供气量 ${supply.value} 万方比较，峰值期计算缺口 ${gap.toFixed(2)} 万方。`:'所填供气量覆盖各期计算需求。'}messages.value.push({role:'assistant',agent:'WorkBuddy 协同助理',model:modelName.value,text:`已按「${object.value} / ${period.value} / ${scene.value.unit}」生成计算结果。${advice}`})}
watch(selectedCustomerIds,()=>{if(scene.value.id==='短期客户'){object.value=selectedCustomers.value[0]?.name||'';saveParameters();snapshot()}},{deep:true})
