/* Task-oriented workspace, separate from the display dashboard. */
.wb{background:#fff;color:var(--wb-ui-text);height:100dvh;overflow:hidden;font-family:'PingFang SC','Microsoft YaHei',sans-serif}
.wb-header{height:58px;background:#fff;border-bottom:1px solid var(--wb-ui-border);gap:22px;padding:0 24px}
.wb-header>a:first-child{font-size:14px;color:var(--wb-ui-secondary)}.wb-header strong{font-size:20px;color:var(--wb-ui-text)}.wb-header strong span{font-size:13px;color:#9195a1}.wb-header a{color:var(--wb-ui-secondary);font-size:13px}.wb-demo{border:0;background:var(--wb-ui-surface);color:var(--wb-ui-secondary);font-size:12px}
.wb-layout{height:calc(100dvh - 58px);min-height:0;grid-template-columns:216px minmax(0,1fr) 270px}
.wb-layout.settings-hidden{grid-template-columns:216px minmax(0,1fr)}.settings-hidden .wb-settings{display:none}
.wb-sidebar{background:var(--wb-ui-surface);border-color:var(--wb-ui-surface);padding:18px 12px;overflow:auto;display:flex;flex-direction:column}
.wb-sidebar .wb-new-task{border:1px solid var(--wb-ui-border);background:#fff;border-radius:8px;text-align:center;padding:11px;color:var(--wb-ui-text);font-weight:600;margin-bottom:25px;box-shadow:0 2px 3px #20212404}
.wb-label{color:var(--wb-ui-muted);font-size:11px;margin:0 10px 12px;letter-spacing:.7px}
.wb-sidebar button{border-radius:7px;padding:11px 12px;margin-bottom:4px;color:var(--wb-ui-secondary);font-size:14px}.wb-sidebar button small{font-size:11px;color:var(--wb-ui-muted);line-height:1.5}.wb-sidebar button.chosen{background:var(--wb-ui-surface);border-color:transparent;color:var(--wb-ui-accent)}.wb-sidebar button.chosen small{color:var(--wb-ui-muted)}.wb-side-note{margin-top:auto;color:var(--wb-ui-muted);font-size:11px;line-height:1.8}
.wb-conversation{position:relative;overflow:hidden;padding:22px clamp(20px,4vw,70px) 16px;max-width:1200px;width:100%;margin:0 auto}.wb-title{flex-shrink:0}.wb-title .wb-label{margin-left:0;font-size:11px}.wb-title h1{font-size:19px;font-weight:600;margin-bottom:7px}.wb-title p:last-child{font-size:13px;color:var(--wb-ui-muted)}.wb-secondary{border-color:var(--wb-ui-border);color:#737a87;background:#fff;font-size:12px}.wb-context{flex-shrink:0;background:var(--wb-ui-surface);color:var(--wb-ui-secondary);font-size:12px;margin:16px 0;padding:10px 12px;border:1px solid var(--wb-ui-surface)}.wb-context b{color:var(--wb-ui-secondary)}
.wb-messages{overflow-y:auto;min-height:0;padding:0 6px 15px;scrollbar-width:thin}.wb-welcome{max-width:640px;margin:clamp(25px,7vh,85px) auto 24px}.wb-orb{background:linear-gradient(135deg,var(--wb-ui-muted),var(--wb-ui-accent));color:white;box-shadow:0 9px 25px #20212425;border:0;border-radius:18px;width:54px;height:54px;font-size:27px;margin-bottom:23px}.wb-welcome h2{font-size:24px;font-weight:600;letter-spacing:-.5px}.wb-welcome>p{font-size:13px;color:var(--wb-ui-muted);margin:12px 0 30px}.wb-welcome button{background:#fff;border-color:var(--wb-ui-border);color:var(--wb-ui-secondary);font-size:14px;padding:14px 16px;margin:9px 0;border-radius:9px;box-shadow:0 2px 5px #20212403}.wb-welcome button span{color:var(--wb-ui-muted)}.wb-welcome button:hover{background:var(--wb-ui-surface);border-color:var(--wb-ui-border)}
.wb-composer{flex-shrink:0;background:#fff;border:1px solid var(--wb-ui-border);box-shadow:0 4px 22px #20212410;padding:13px 16px;border-radius:14px;margin-top:12px}.wb-composer textarea{color:var(--wb-ui-text);min-height:64px;font-size:14px}.wb-composer textarea::placeholder{color:var(--wb-ui-muted)}.wb-composer small{color:var(--wb-ui-muted);font-size:11px}.wb-composer button{background:var(--wb-ui-accent);border-radius:8px;font-size:13px;padding:8px 18px}
.wb-settings{overflow:auto;background:var(--wb-ui-surface);border-color:var(--wb-ui-surface);padding:25px 18px}.wb-settings>.wb-label{margin-left:0}.wb-settings h2{font-size:15px;color:var(--wb-ui-text);margin-bottom:24px}.wb-settings label{color:var(--wb-ui-secondary);font-size:13px;margin:20px 0}.wb-settings select,.wb-settings input{background:#fff;border-color:var(--wb-ui-border);color:var(--wb-ui-secondary);font-size:13px;padding:10px}.wb-settings-note{border-color:var(--wb-ui-surface);margin-top:26px}.wb-settings-note strong{color:var(--wb-ui-secondary);font-size:12px}.wb-settings-note p{color:var(--wb-ui-muted);font-size:12px}.wb-message small{color:var(--wb-ui-muted)}.wb-message p,.wb-message.user p{color:var(--wb-ui-secondary);font-size:14px}.wb-avatar{background:var(--wb-ui-surface);color:var(--wb-ui-muted)}.wb-message.user .wb-avatar{background:var(--wb-ui-surface);color:var(--wb-ui-muted)}
.wb-result{background:var(--wb-ui-surface);border-color:var(--wb-ui-border)}.wb-result-head h3{font-size:14px;color:var(--wb-ui-text)}.wb-result-head span{color:#9a834d}.wb-result>p{color:var(--wb-ui-muted)}.wb-summary{color:var(--wb-ui-muted)}.wb-summary strong{color:var(--wb-ui-muted)}.wb-bars{border-color:var(--wb-ui-border)}.wb-bars span{background:linear-gradient(var(--wb-ui-muted),var(--wb-ui-accent))}.wb-bars small{color:var(--wb-ui-muted)}.wb-result details{color:var(--wb-ui-secondary)}.wb-result th{background:var(--wb-ui-surface);color:var(--wb-ui-secondary)}.wb-result td{border-color:var(--wb-ui-border)}
@media(max-width:1100px) and (min-width:761px){.wb-layout{grid-template-columns:185px minmax(0,1fr) 230px}.wb-layout.settings-hidden{grid-template-columns:185px minmax(0,1fr)}.wb-conversation{padding:20px}.wb-welcome h2{font-size:21px}}
@media(max-width:760px){.wb{height:auto;min-height:100dvh;overflow:auto}.wb-layout,.wb-layout.settings-hidden{height:auto;display:flex}.wb-sidebar{flex-direction:row}.wb-sidebar .wb-new-task{margin:0}.wb-side-note{display:none}.wb-settings{max-height:320px}.wb-conversation{min-height:650px}.wb-messages{max-height:65vh;min-height:250px}.wb-header{height:58px}.wb-welcome h2{font-size:20px}}


.wb-send-controls{display:flex;align-items:center;gap:10px;flex-shrink:0}.wb-model-picker{position:relative}.wb-composer .wb-model-toggle{background:var(--wb-ui-surface);color:var(--wb-ui-secondary);border:1px solid var(--wb-ui-border);border-radius:20px;padding:7px 12px;font-size:13px;white-space:nowrap}.wb-model-toggle span{margin-left:8px;color:var(--wb-ui-muted)}.wb-composer .wb-model-backdrop{position:fixed;inset:0;z-index:20;background:transparent;border-radius:0;cursor:default}.wb-model-menu{position:absolute;bottom:45px;right:0;width:280px;z-index:21;padding:8px;border:1px solid var(--wb-ui-border);background:#fff;border-radius:14px;box-shadow:0 10px 40px #20212424}.wb-model-menu>p{padding:9px 10px;color:var(--wb-ui-secondary);font-size:13px}.wb-model-menu>p small{float:right;color:var(--wb-ui-muted);font-size:11px}.wb-composer .wb-model-menu>button{background:#fff;color:var(--wb-ui-secondary);display:flex;align-items:center;justify-content:space-between;width:100%;padding:11px;text-align:left;border-radius:8px}.wb-composer .wb-model-menu>button:hover,.wb-composer .wb-model-menu>button[aria-checked="true"]{background:var(--wb-ui-surface)}.wb-model-menu strong{font-size:14px;font-weight:500}.wb-model-menu button small{display:block;margin-top:4px;font-size:11px;color:var(--wb-ui-muted)}.wb-model-menu button>span{color:var(--wb-ui-accent)}.wb-model-menu footer{margin:6px 4px 0;padding:10px 4px 4px;border-top:1px solid var(--wb-ui-surface);font-size:11px;color:var(--wb-ui-muted);display:block}

.wb-scene-bar{display:flex;align-items:center;justify-content:space-between;gap:10px;border-bottom:1px solid var(--wb-ui-surface);padding:0 0 10px;margin-bottom:10px}.wb-scene-bar label{display:flex;align-items:center;gap:10px;font-size:12px;color:var(--wb-ui-muted)}.wb-scene-bar select{font:inherit;font-size:13px;border:1px solid var(--wb-ui-border);border-radius:6px;background:var(--wb-ui-surface);color:var(--wb-ui-secondary);padding:5px 10px}.wb-scene-bar>span{font-size:11px;color:var(--wb-ui-muted)}.wb-sidebar button span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.wb-sidebar button small{font-size:11px}

.wb-layout{grid-template-columns:250px minmax(0,1fr) 270px}.wb-layout.settings-hidden{grid-template-columns:250px minmax(0,1fr)}
.wb-sidebar{background:#f7f7f8;padding:22px 12px;gap:3px}.wb-side-brand{padding:0 12px 23px;font-size:20px;font-weight:700;white-space:nowrap;color:#202124}.wb-side-brand small{font-weight:400;font-size:11px;color:#a0a0a5;margin-left:4px}.wb-sidebar .wb-nav-item{display:flex;align-items:center;gap:10px;font-size:14px;font-weight:500;color:#292a2e;width:100%;padding:11px 12px;margin:0;border:0;border-radius:10px}.wb-sidebar .wb-nav-item.active,.wb-sidebar .wb-nav-item:hover{background:#ececee}.wb-nav-icon{font-size:22px;width:24px;text-align:center;line-height:1}.wb-sidebar .wb-beta{font-size:11px;border:1px solid #d8d8dc;color:#999;border-radius:14px;margin:0;padding:2px 7px}.wb-recent-label{margin:30px 12px 12px;font-size:13px;font-weight:500;color:#999}.wb-sidebar .wb-session-item{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:11px 12px;border:0;margin:0;font-size:13px;border-radius:9px}.wb-sidebar .wb-session-item.chosen{background:#eaeaec;color:#26282c}.wb-sidebar .wb-session-item small{white-space:nowrap;font-size:11px;color:#999;margin:0}.wb-session-item span{min-width:0}.wb-sidebar-home{margin-top:auto;padding:25px 12px 0;color:#9ba0a8;font-size:12px;text-decoration:none}.wb-resource-backdrop{position:fixed;inset:58px 0 0 250px;background:#20212430;z-index:30;display:flex;align-items:flex-start;padding:24px;backdrop-filter:blur(3px)}.wb-resource{max-height:calc(100dvh - 110px);overflow:auto;background:white;padding:25px;border-radius:15px;width:700px;box-shadow:0 12px 50px #20212420}.wb-resource-heading{display:flex;justify-content:space-between;align-items:center}.wb-resource-heading h2{font-size:20px}.wb-resource-heading button{color:#9399a3;font-size:13px}.wb-resource>p{font-size:13px;color:var(--wb-ui-muted);margin:20px 0}.wb-resource-tabs{display:flex;gap:26px;border-bottom:1px solid var(--wb-ui-surface);margin-top:25px;padding-bottom:14px;font-size:14px;color:#aaa}.wb-resource-tabs strong{color:var(--wb-ui-secondary)}.wb-expert-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.wb-expert-grid button{border:1px solid var(--wb-ui-border);text-align:left;padding:18px;border-radius:10px}.wb-expert-grid strong{display:block;font-size:14px;color:var(--wb-ui-text)}.wb-expert-grid small{display:block;font-size:12px;color:var(--wb-ui-muted);line-height:1.6;margin:8px 0 18px}.wb-expert-grid button>span{font-size:12px;color:var(--wb-ui-muted)}.wb-expert-grid button:hover{background:var(--wb-ui-surface);border-color:var(--wb-ui-border)}.wb-library-item{display:block;text-align:left;border:1px solid var(--wb-ui-border);border-radius:9px;padding:15px;width:100%;margin:12px 0;color:var(--wb-ui-text)}.wb-library-item small{display:block;font-size:12px;color:var(--wb-ui-muted);margin-top:8px}.wb-empty-resource{text-align:center;padding:50px 20px}.wb-empty-resource p{font-size:13px;color:var(--wb-ui-muted);margin:15px 0 25px}.wb-empty-resource button{background:var(--wb-ui-muted);color:white;border-radius:7px;padding:10px 20px;font-size:13px}@media(max-width:1100px) and (min-width:761px){.wb-layout{grid-template-columns:220px minmax(0,1fr) 230px}.wb-layout.settings-hidden{grid-template-columns:220px minmax(0,1fr)}.wb-resource-backdrop{left:220px}}@media(max-width:760px){.wb-resource-backdrop{left:0;padding:12px}.wb-expert-grid{grid-template-columns:1fr}.wb-side-brand,.wb-recent-label,.wb-session-item,.wb-sidebar-home{display:none}.wb-sidebar .wb-nav-item{width:auto;font-size:13px;padding:7px}.wb-nav-icon{font-size:17px;width:18px}.wb-layout{display:flex}}

.wb-team-strip{flex-shrink:0;border:1px solid var(--wb-ui-border);background:var(--wb-ui-surface);border-radius:10px;padding:12px 14px;margin-bottom:15px}.wb-team-strip>div:first-child{display:flex;align-items:center;gap:12px}.wb-team-strip strong{font-size:13px;color:var(--wb-ui-secondary)}.wb-team-strip>div>span{font-size:11px;color:var(--wb-ui-muted)}.wb-team-strip button{margin-left:auto;font-size:12px;color:var(--wb-ui-muted)}.wb-team-chips{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}.wb-team-strip .wb-team-chips span{font-size:11px;padding:4px 8px;border-radius:5px;background:var(--wb-ui-surface);color:var(--wb-ui-muted);border:1px solid var(--wb-ui-border)}.wb-team-strip .wb-team-chips span.participating{background:var(--wb-ui-surface);border-color:var(--wb-ui-border);color:var(--wb-ui-muted)}.wb-collaboration{border-bottom:1px solid var(--wb-ui-border);padding-bottom:15px;margin-bottom:20px}.wb-collaboration>h3{font-size:14px;color:var(--wb-ui-secondary)}.wb-collaboration>h3 small{font-size:11px;font-weight:400;color:var(--wb-ui-muted);margin-left:10px}.wb-collaboration>p{font-size:12px;color:var(--wb-ui-muted);margin-top:8px}.wb-collab-step{display:flex;align-items:center;gap:10px;margin-top:13px}.wb-collab-step>span{display:grid;place-items:center;width:23px;height:23px;border-radius:50%;background:var(--wb-ui-surface);color:var(--wb-ui-muted);font-size:11px;flex-shrink:0}.wb-collab-step strong{font-size:12px;font-weight:500;color:var(--wb-ui-secondary)}.wb-collab-step p{font-size:11px;color:var(--wb-ui-muted);margin-top:4px}.wb-collab-step>small{margin-left:auto;color:#70a68b;font-size:11px;white-space:nowrap}.wb-expert-description{background:var(--wb-ui-surface);padding:15px;font-size:13px!important;line-height:1.8;color:var(--wb-ui-secondary)!important;border-radius:8px}
